code.cpp:
class Solution {
public:
    int numMatchingSubseq(string s, vector<string>& words) {
        vector<vector<pair<int,int>>> buckets(26);
        for (int i = 0; i < (int)words.size(); i++) {
            buckets[words[i][0] - 'a'].push_back({i, 0});
        }
        int count = 0;
        for (char c : s) {
            int idx = c - 'a';
            vector<pair<int,int>> current;
            current.swap(buckets[idx]);
            for (auto& [wi, ci] : current) {
                ci++;
                if (ci == (int)words[wi].size()) {
                    count++;
                } else {
                    buckets[words[wi][ci] - 'a'].push_back({wi, ci});
                }
            }
        }
        return count;
    }
};
